const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function evaluateInvite(email) {
  const normalized = String(email ?? '').trim().toLowerCase();
  if (!normalized) return { ok: false, email: null, message: 'Enter an email address to continue.' };
  if (!EMAIL.test(normalized)) return { ok: false, email: null, message: 'Enter a valid email address.' };
  return { ok: true, email: normalized, message: `Invitation sent to ${normalized}.` };
}

