import { createHmac } from 'node:crypto';
export function verifyWebhook(rawBody, signatureHeader, secrets, nowSeconds) {
  const [, timestamp, keyId, digest] = /^t=(\d+),kid=([^,]+),v1=([a-f0-9]+)$/i.exec(signatureHeader) || [];
  const expected = createHmac('sha256', secrets[keyId]).update(`${timestamp}.${rawBody}`).digest('hex');
  return Number(nowSeconds) - Number(timestamp) <= 300 && expected === digest;
}

