    if (typeof rawBody !== 'string' && !Buffer.isBuffer(rawBody)) return false;
    if (typeof signatureHeader !== 'string' || secrets === null || typeof secrets !== 'object' || Array.isArray(secrets)) return false;
    const match = HEADER.exec(signatureHeader);
    if (!match || !Object.hasOwn(secrets, match[2])) return false;
    const timestamp = Number(match[1]);
    if (!Number.isSafeInteger(timestamp) || !Number.isSafeInteger(nowSeconds) || Math.abs(nowSeconds - timestamp) > 300) return false;
    const secret = secrets[match[2]];
    if (typeof secret !== 'string' || !secret) return false;
    const body = Buffer.isBuffer(rawBody) ? rawBody : Buffer.from(rawBody);
    const signed = Buffer.concat([Buffer.from(`${match[1]}.`, 'ascii'), body]);
    const expected = createHmac('sha256', secret).update(signed).digest();
    const supplied = Buffer.from(match[3], 'hex');
    return supplied.length === expected.length && timingSafeEqual(supplied, expected);
